if (element.querySelector('.product-reviews-grid-injected')) return;

const gridSection = document.createElement('section');
gridSection.setAttribute('aria-label', 'Product Reviews & Deals');
gridSection.className = 'card Card--card--qJMOC Card--cardPadded--d1sUG Card--containerQuery--+S0OY product-reviews-grid-injected';
gridSection.style.cssText = 'margin-top:24px;background:#fff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.08);overflow:hidden;';

const header = document.createElement('header');
header.className = 'Card--cardHeader--AE3k1';
header.style.cssText = 'padding:20px 24px 0;display:flex;justify-content:space-between;align-items:center;';

const title = document.createElement('h2');
title.className = 'Card--cardHeading--M6yBx';
title.textContent = '🏕️ Outdoor Gear Reviews & Deals';
title.style.cssText = 'font-size:22px;font-weight:700;margin:0;color:#1a1a1a;';

const headerLink = document.createElement('a');
headerLink.href = 'https://weather.com/atmosphere';
headerLink.target = '_self';
headerLink.style.cssText = 'color:#0077b6;text-decoration:none;font-weight:600;font-size:14px;display:flex;align-items:center;gap:4px;';
headerLink.textContent = 'See more →';

header.appendChild(title);
header.appendChild(headerLink);
gridSection.appendChild(header);

const grid = document.createElement('div');
grid.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fill, minmax(280px, 1fr));gap:20px;padding:24px;';

const products = [
  { title: 'Best Sunscreen Of 2026: Our Top 10 Picks', img: 'https://s.w-x.co/PanamaJackBabySunscreen-HERO-Amazon.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=70', url: 'https://weather.com/atmosphere/reviews/best-sunscreen', tag: 'Sun Protection', color: '#fff3e0' },
  { title: '17 Popular Sun Shirts For Men And Women', img: 'https://s.w-x.co/WomensSunshirt-HERO-Amazon.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=70', url: 'https://weather.com/atmosphere/reviews/long-sleeve-sun-shirts-men-and-women', tag: 'Clothing', color: '#e3f2fd' },
  { title: '12 Travel Essentials To Stash In Your Carry-On', img: 'https://s.w-x.co/TravelInspira-luggagescale-HERO.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=70', url: 'https://weather.com/atmosphere/reviews/best-travel-products', tag: 'Travel Gear', color: '#e8f5e9' },
  { title: 'Why You Need A Silk Pillowcase (And Our Top Picks)', img: 'https://s.w-x.co/BrooklinenSilkPillow-HERO.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=70', url: 'https://weather.com/atmosphere/reviews/best-silk-pillowcases', tag: 'Wellness', color: '#fce4ec' },
  { title: 'Fight The Frizz: Best Hair Oils Of 2026', img: 'https://s.w-x.co/OuaiHairOil-HERO-Sephora.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=70', url: 'https://weather.com/atmosphere/reviews/best-hair-oils-for-every-type-of-hair', tag: 'Hair Care', color: '#f3e5f5' },
  { title: "Last Minute Mother's Day Gifts That Can Still Arrive On Time", img: 'https://s.w-x.co/FerreroCollection-HERO1-Amazon.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=70', url: 'https://weather.com/atmosphere/reviews/last-minute-mothers-day-gift-ideas', tag: 'Gifts', color: '#fff8e1' }
];

products.forEach(p => {
  const card = document.createElement('a');
  card.href = p.url;
  card.target = '_self';
  card.style.cssText = 'display:flex;flex-direction:column;border-radius:12px;overflow:hidden;text-decoration:none;transition:transform 0.2s ease,box-shadow 0.2s ease;background:#fafafa;box-shadow:0 1px 4px rgba(0,0,0,0.06);cursor:pointer;';
  card.addEventListener('mouseenter', () => { card.style.transform = 'translateY(-4px)'; card.style.boxShadow = '0 8px 24px rgba(0,0,0,0.12)'; });
  card.addEventListener('mouseleave', () => { card.style.transform = 'translateY(0)'; card.style.boxShadow = '0 1px 4px rgba(0,0,0,0.06)'; });

  const imgWrap = document.createElement('div');
  imgWrap.style.cssText = 'position:relative;width:100%;padding-top:60%;overflow:hidden;background:' + p.color + ';';

  const img = document.createElement('img');
  img.src = p.img;
  img.alt = p.title;
  img.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;object-fit:cover;transition:transform 0.3s ease;';
  img.addEventListener('error', () => { img.style.display = 'none'; });
  card.addEventListener('mouseenter', () => { img.style.transform = 'scale(1.05)'; });
  card.addEventListener('mouseleave', () => { img.style.transform = 'scale(1)'; });

  const tag = document.createElement('span');
  tag.textContent = p.tag;
  tag.style.cssText = 'position:absolute;top:10px;left:10px;background:rgba(0,0,0,0.6);color:#fff;padding:4px 10px;border-radius:20px;font-size:11px;font-weight:600;letter-spacing:0.5px;text-transform:uppercase;';

  imgWrap.appendChild(img);
  imgWrap.appendChild(tag);

  const content = document.createElement('div');
  content.style.cssText = 'padding:16px;flex:1;display:flex;flex-direction:column;justify-content:space-between;';

  const cardTitle = document.createElement('p');
  cardTitle.textContent = p.title;
  cardTitle.style.cssText = 'margin:0 0 8px;font-size:15px;font-weight:600;line-height:1.4;color:#1a1a1a;';

  const cardFooter = document.createElement('div');
  cardFooter.style.cssText = 'display:flex;align-items:center;gap:6px;';
  const readMore = document.createElement('span');
  readMore.textContent = 'Read Review';
  readMore.style.cssText = 'font-size:13px;font-weight:600;color:#0077b6;';
  const arrow = document.createElement('span');
  arrow.textContent = '→';
  arrow.style.cssText = 'color:#0077b6;transition:transform 0.2s;';
  card.addEventListener('mouseenter', () => { arrow.style.transform = 'translateX(4px)'; });
  card.addEventListener('mouseleave', () => { arrow.style.transform = 'translateX(0)'; });
  cardFooter.appendChild(readMore);
  cardFooter.appendChild(arrow);

  content.appendChild(cardTitle);
  content.appendChild(cardFooter);
  card.appendChild(imgWrap);
  card.appendChild(content);
  grid.appendChild(card);
});

gridSection.appendChild(grid);
element.parentNode.insertBefore(gridSection, element.nextSibling);
